class ADS1115_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16

    def __init__(self):
        super().__init__()
        self.regs = {
            0x00: 0x0000,  # CONVERSION
            0x01: 0x8583,  # CONFIG
            0x02: 0x8000,  # LO_THRESH
            0x03: 0x7FFF   # HI_THRESH
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if nbytes == 1:
            return (self.regs[addr] & 0xFF00) >> 8
        else:
            return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if nbytes == 1:
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        else:
            self.regs[addr] = data

